def parse_lane(spec: str) -> tuple:
    if ',model=' not in spec:
        raise ValueError("spec lacks the literal ',model=' marker")

    parts = spec.split(',model=', 1)  # Split at first occurrence of ',model='
    if len(parts) < 2:
        raise ValueError("spec lacks the literal ',model=' marker")

    model = parts[1].strip()

    # Split the first part (before ',model=') at the first '='
    if '=' not in parts[0]:
        raise ValueError("part before ',model=' contains no '='")

    name_url_part = parts[0].split('=', 1)
    if len(name_url_part) != 2:
        raise ValueError("part before ',model=' contains no '='")

    name = name_url_part[0].strip()
    url = name_url_part[1].strip()

    # Remove trailing slash from url
    url = url.rstrip('/')

    return (name, url, model)

