def dominant_case(words: list[str]) -> str:
    if not words:
        return "none"

    count = {"upper": 0, "lower": 0, "mixed": 0}

    for word in words:
        has_upper = False
        has_lower = False

        # Check only letters
        for c in word:
            if c.isalpha():
                if c.isupper():
                    has_upper = True
                if c.islower():
                    has_lower = True

        if not has_upper and not has_lower:
            # no letters at all - ignore
            continue

        if has_upper and has_lower:
            count["mixed"] += 1
        elif has_upper:
            count["upper"] += 1
        elif has_lower:
            count["lower"] += 1

    # Tie-break: return first in order "upper", "lower", "mixed"
    max_count = max(count["upper"], count["lower"], count["mixed"])

    if count["upper"] == max_count:
        return "upper"
    elif count["lower"] == max_count:
        return "lower"
    else:
        return "mixed"

def chunk_sequence(items: list, size: int, policy: str, fill=None) -> list:
    if not items:
        return []

    if size <= 0:
        raise ValueError("size must be greater than 0")

    if policy not in ("keep", "drop", "pad"):
        raise ValueError(f"policy must be one of 'keep', 'drop', 'pad'; got {policy}")

    if len(items) % size == 0:
        # final chunk is exactly size, so policy doesn't apply
        return [items[i:i+size] for i in range(0, len(items), size)]

    # final chunk is shorter than size
    chunks = []
    for i in range(0, len(items) - (len(items) % size), size):
        chunks.append(items[i:i+size])

    # handle the short final chunk
    remainder = items[len(items) - (len(items) % size):]
    if policy == "keep":
        chunks.append(remainder)
    elif policy == "drop":
        pass  # do nothing, just skip the remainder
    elif policy == "pad":
        # pad with fill until length is size
        padded = remainder + [fill] * (size - len(remainder))
        chunks.append(padded)

    return chunks

