def invert_to_groups(mapping: dict) -> dict:
    inverted = {}
    for key, value in mapping.items():
        if value not in inverted:
            inverted[value] = []
        inverted[value].append(key)
    # Sort the list of keys for each value
    for value in inverted:
        inverted[value].sort()
    return inverted

def merge_layers(layers: list) -> dict:
    """Merge a list of configuration dictionaries into one."""
    if not layers:
        return {}

    result = {}
    for layer in layers:
        # Check if each layer is a dictionary
        if not isinstance(layer, dict):
            raise TypeError(f"Expected a dictionary, got {type(layer).__name__}")

        for key, value in layer.items():
            if value is None:
                # Remove the key from result if it exists
                if key in result:
                    del result[key]
            else:
                # Keep or set the value
                result[key] = value

    return result

def top_tags(tags: list, n: int) -> list:
    if n < 0:
        raise ValueError("n cannot be negative")
    if n == 0:
        return []
    if not tags:
        return []

    # Count frequency of each tag
    tag_count = {}
    for tag in tags:
        tag_count[tag] = tag_count.get(tag, 0) + 1

    # Get the n most frequent tags
    items = list(tag_count.items())

    # Sort by count (descending), then by tag (ascending) in case of ties
    items.sort(key=lambda x: (-x[1], x[0]))

    # Return top n tags
    return items[:n]

def validation_parse_seat_code(code: str) -> tuple[int, str]:
    if len(code) < 1:
        raise ValueError

    # The last character must be an uppercase letter A-F
    if not code[-1].isupper():
        raise ValueError
    if code[-1] not in "ABCDEF":
        raise ValueError

    # Everything before the last character is the row
    row_part = code[:-1]
    if not row_part:
        raise ValueError

    # Check if row_part contains only digits
    if not row_part.isdigit():
        raise ValueError

    # Check for leading zero - row should not have leading zero
    if row_part[0] == "0":
        raise ValueError

    # Convert row_part to integer and validate range
    row = int(row_part)
    if row < 1 or row > 60:
        raise ValueError

    return (row, code[-1])

