function Get-PythonTag {
    param([string] $Version, [switch] $FreeThreaded)

    # Check PowerShell version at runtime - fails immediately on 5.1
    if ($PSVersionTable.PSVersion.Major -lt 7) {
        throw [System.ArgumentException]::new("PowerShell 7.0 or higher is required to run this script")
    }

    $v = $Version ?? ''
    $v = $v.Trim() ? $v.Trim() : '3.14'
    return $FreeThreaded ? "${v}t" : $v
}

function Import-BuildModule {
    param(
        [Parameter(Mandatory)] [string[]] $Name,
        [Parameter(Mandatory)] [string] $ModuleRoot
    )
    foreach ($n in $Name) {
        $path = Join-Path $ModuleRoot "$n.psm1"
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            throw "Build module '$n' not found at $path"
        }
        Import-Module $path -Force
    }
    # Ensure WindowsScripts.Shared functions are available
    $sharedPath = Join-Path $ModuleRoot "WindowsScripts.Shared.psm1"
    if (-not (Test-Path -LiteralPath $sharedPath -PathType Leaf)) {
        throw "WindowsScripts.Shared.psm1 not found at $sharedPath"
    }
    Import-Module $sharedPath -Force
}

function Get-LaneNames {
    param(
        [string] $Spec
    )

    if ([string]::IsNullOrEmpty($Spec)) {
        return @()
    }

    $lanes = $Spec -split ',' -match '^\s*(\S+)\s*$'
    $result = @()
    foreach ($item in $lanes) {
        $trimmed = $item.Trim()
        if ($trimmed -ne '') {
            $result += $trimmed
        }
    }

    return $result
}

