function Read-PinnedVersion {
    param([Parameter(Mandatory)] [string] $Path)
    try {
        $line = Get-Content -LiteralPath $Path -TotalCount 1 -ErrorAction Stop
        return "$line".Trim()
    }
    catch {
        # Only catch when the file doesn't exist or is a directory
        if ($null -ne $PSItem -and $PSItem.Exception -is [System.IO.DirectoryNotFoundException]) {
            return 'unknown'
        }
        # If we reach here, it's not a valid file (e.g. directory or access issue)
        return 'unknown'
    }
}
